{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0001",
          "reason": "Formal constitutional authority only; it is context for exposure, not evidence of any 2022 nuclear-risk choice."
        },
        {
          "evidence_id": "E0012",
          "reason": "Post-period cybersecurity strategy; useful for dual-use context, but not contemporaneous 2022 conduct."
        },
        {
          "evidence_id": "E0013",
          "reason": "Conventional-security de-escalation and eastern-crisis diplomacy, not nuclear command or existential-risk conduct."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct 2022 nuclear/existential-risk decision by Tshisekedi is evidenced, and the package never shows operational nuclear control, brinkmanship, or safeguard intervention.",
          "lenses": [
            "1B.1",
            "1B.3",
            "1B.4",
            "1B.7",
            "1B.8",
            "1B.9",
            "1B.10"
          ],
          "best_source_or_query_direction": "Full text of the 15 August 2022 presidential ordinance, any 2022 DRC statements at TPNW/NPT/CTBTO venues, and IAEA/UNODA/CTBTO records for DRC-specific nuclear facilities or safeguards actions.",
          "why_it_matters": "Without a target-period ruler choice or command decision, the chapter remains almost entirely legal posture and non-nuclear context."
        }
      ],
      "reason": "The package shows treaty/legal nonproliferation posture and some cyber-risk governance, but no ruler-level nuclear command, custody, brinkmanship, or other discriminating existential-risk choice in 2022."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0017",
          "reason": "Disputed cross-border accusation/denial material; keep as conflict context, not as settled proof of Tshisekedi conduct."
        },
        {
          "evidence_id": "E0024",
          "reason": "Humanitarian harm from the eastern conflict is relevant background, but it is not direct evidence of ruler-attributed aggression."
        },
        {
          "evidence_id": "E0034",
          "reason": "Synthesis article with analytical framing; it should support end-state context, not carry primary attribution weight."
        }
      ],
      "material_gaps": [],
      "reason": "The package fairly presents Tshisekedi's peace-process participation, crisis diplomacy, inherited conflict pressure, and contrary evidence, while separating rebel and regional violence from his own attributable conduct."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0042",
          "reason": "Provincial arrest/protest incident; relevant to domestic safety, but it should not be generalized into stronger national-level conduct than the source supports."
        },
        {
          "evidence_id": "E0045",
          "reason": "Conflict-driven displacement is important context, but it is not direct presidential abuse evidence."
        },
        {
          "evidence_id": "E0051",
          "reason": "Mixed-actor journalist targeting should remain mixed attribution, not government-only conduct."
        }
      ],
      "material_gaps": [],
      "reason": "The package credibly shows a negative domestic-safety record with state-of-siege abuse, protest killings, detention problems, and some remedial steps, while preserving attribution limits and contrary evidence."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0055",
          "reason": "Useful inherited-environment background, but not a 2022 ruler-specific act."
        },
        {
          "evidence_id": "E0057",
          "reason": "Institutional constraints on CENI are context, not proof of Tshisekedi's democratic intent or restraint."
        },
        {
          "evidence_id": "E0058",
          "reason": "Election calendar setting is procedural context; it should not be mistaken for proof of democratic commitment or fair competition."
        }
      ],
      "material_gaps": [],
      "reason": "The package fairly captures electoral manipulation concerns, opposition pressure, press constraints, and reform rhetoric, while avoiding the mistake of treating inherited institutional weakness as direct ruler merit."
    },
    {
      "chapter_id": "5B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0071",
          "reason": "Budget proposal and stated priorities only; it is planning context, not execution."
        },
        {
          "evidence_id": "E0073",
          "reason": "Macro assumptions in the budget bill are forecasts, not realized outcomes."
        },
        {
          "evidence_id": "E0082",
          "reason": "Rights-crackdown evidence belongs primarily to domestic safety and political-freedom chapters; here it is only indirect business-climate context."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 execution and household/distribution outcome evidence remains thinner than the policy and macro coverage.",
          "lenses": [
            "5B.2",
            "5B.6",
            "5B.8",
            "5B.9",
            "5B.10"
          ],
          "best_source_or_query_direction": "2022 budget execution reports, Cour des comptes or IGF audits, and household-consumption or poverty microdata tied to the 2022 fiscal year.",
          "why_it_matters": "The package can show policy direction and mixed macro results, but not yet fully demonstrate attributable delivery to ordinary households."
        }
      ],
      "reason": "The policy and transparency material is strong, but too much of the package remains plans, recommendations, or country-level outcomes with only partial ruler attribution."
    },
    {
      "chapter_id": "6B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0085",
          "reason": "Country-program framework and priorities are context and intent, not ruler-attributable welfare results."
        },
        {
          "evidence_id": "E0086",
          "reason": "Pre-2022 project design is useful baseline material, but it is not target-period delivery evidence."
        },
        {
          "evidence_id": "E0104",
          "reason": "Survey design and measurement infrastructure are informative, but they do not themselves show ruler-led welfare improvement."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct, nationally representative 2022 welfare-outcome evidence attributable to Tshisekedi remains limited relative to the amount of partner-led program evidence.",
          "lenses": [
            "6B.2",
            "6B.3",
            "6B.5",
            "6B.6",
            "6B.9",
            "6B.10"
          ],
          "best_source_or_query_direction": "INS/DHS or MICS tables, budget-execution documents, and independent completion or evaluation reports for 2022 health, education, WASH, and social-protection spending.",
          "why_it_matters": "The package can fairly present the welfare environment, but stronger attribution is needed to isolate Tshisekedi's own contribution."
        }
      ],
      "reason": "The package captures major welfare deficits and several concrete interventions, but much of the visible delivery is partner-led and the ruler-attributable 2022 outcome picture is still thin."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0113",
          "reason": "Associate-level corruption allegations are network context, not direct proof of Tshisekedi's own deception, benefit, or concealment."
        },
        {
          "evidence_id": "E0114",
          "reason": "Accountability failure and appointment evidence are relevant, but the item does not establish a personal dishonesty finding by itself."
        },
        {
          "evidence_id": "E0115",
          "reason": "This is a public instruction/promise, not evidence that the promised recovery action actually occurred."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct personal-nexus evidence is still sparse: no clear 2022 asset-declaration, campaign-finance, beneficial-ownership, or court/audit record ties Tshisekedi himself to self-dealing or deliberate deception.",
          "lenses": [
            "7B.1",
            "7B.2",
            "7B.3",
            "7B.4",
            "7B.6",
            "7B.7",
            "7B.8",
            "7B.9"
          ],
          "best_source_or_query_direction": "Asset-declaration records, procurement files, campaign-finance disclosures, and court/audit findings that explicitly address Tshisekedi's knowledge, benefit, protection, or concealment.",
          "why_it_matters": "Without direct personal-nexus evidence, the chapter risks collapsing into country corruption and repression context rather than personal integrity review."
        }
      ],
      "reason": "This chapter is not publication-ready: the adverse material is mostly about associates, institutions, or country corruption, while direct evidence of Tshisekedi's own truthfulness, benefit, concealment, or scrutiny response remains too thin."
    },
    {
      "chapter_id": "8B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0116",
          "reason": "Official program description is self-presentation, not execution evidence."
        },
        {
          "evidence_id": "E0117",
          "reason": "Budget proposal documents are plans and funding intent, not proof of implementation."
        },
        {
          "evidence_id": "E0124",
          "reason": "End-of-year address is self-assessment and should be triangulated with independent outcome data."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent, audited delivery and outcome evidence is thinner than the program rhetoric and internal reporting.",
          "lenses": [
            "8B.2",
            "8B.3",
            "8B.6",
            "8B.7",
            "8B.8",
            "8B.10"
          ],
          "best_source_or_query_direction": "Budget-execution reports, Cour des comptes or IGF audits, and independent completion reports for PDL-145T, ANSER, telecom reform, and related implementation tracks.",
          "why_it_matters": "The package can outline a program-to-implementation story, but final competence assessment needs more independently verified delivery data."
        }
      ],
      "reason": "The package offers a coherent program-and-implementation narrative, but too much of it is self-report or indirect; stronger audited delivery evidence is needed to settle competence cleanly."
    }
  ]
}
